INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kann ich Optimierungspotenziale ohne Analyse erkennen?', 2, '[{"text": "Nein", "correct": true, "because": "Analyse zeigt Schwächen"}, {"text": "Ja", "correct": false, "because": "Ohne Daten ungenau"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Erkennung von Optimierungspotenzialen?', 3, '[{"text": "Effizienzsteigerung", "correct": true, "because": "Verbessert Prozesse"}, {"text": "Design", "correct": false, "because": "Anderer Fokus"}, {"text": "Marketing", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden helfen bei der Erkennung von Optimierungspotenzialen?', 5, '[{"text": "Profiling", "correct": true, "because": "Misst Leistung"}, {"text": "Prozessanalyse", "correct": true, "because": "Findet Engpässe"}, {"text": "Zufälliges Raten", "correct": false, "because": "Unzuverlässig"}, {"text": "UI-Design", "correct": false, "because": "Oberflächlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Optimierungspotenziale brauchen Daten. b) Sie betreffen nur Code.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) auch Prozesse"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Erkennung von Optimierungspotenzialen?', 4, '[{"text": "Leistungsmetriken", "correct": false, "because": "Zeigt Schwächen"}, {"text": "Prozessfluss", "correct": false, "because": "Findet Ineffizienzen"}, {"text": "Schriftfarbe", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Optimierungspotenziale immer offensichtlich sind?', 2, '[{"text": "Nein", "correct": true, "because": "Manche versteckt"}, {"text": "Ja", "correct": false, "because": "Nicht immer klar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool nutze ich für die Prozessanalyse?', 3, '[{"text": "BPMN", "correct": true, "because": "Visualisiert Prozesse"}, {"text": "Notepad", "correct": false, "because": "Unstrukturiert"}, {"text": "E-Mail", "correct": false, "because": "Unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen die Erkennung von Optimierungspotenzialen effektiv?', 5, '[{"text": "Datenbasis", "correct": true, "because": "Belegt Schwächen"}, {"text": "Messbarkeit", "correct": true, "because": "Quantifiziert Potenziale"}, {"text": "Hohe Auflösung", "correct": false, "because": "Irrelevant"}, {"text": "Lange Berichte", "correct": false, "because": "Ermüdend"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Optimierungspotenziale sind nur technisch. b) Prozesse sind unwichtig. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "Auch organisatorisch, Prozesse zentral"}, {"text": "Beides stimmt", "correct": false, "because": "Nicht korrekt"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) unvollständig"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Erkennung von Optimierungspotenzialen?', 4, '[{"text": "Metriken", "correct": false, "because": "Misst Leistung"}, {"text": "Prozessdaten", "correct": false, "because": "Zeigt Engpässe"}, {"text": "Teamfotos", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Optimierungspotenziale nur für Performance?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Sicherheit, Kosten"}, {"text": "Ja", "correct": false, "because": "Nicht exklusiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Daten sind für die Erkennung entscheidend?', 4, '[{"text": "Laufzeiten", "correct": true, "because": "Zeigt Ineffizienzen"}, {"text": "Fehlerquoten", "correct": true, "because": "Identifiziert Schwächen"}, {"text": "UI-Design", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Optimierungspotenziale ohne Messung erkennbar sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Messung belegt"}, {"text": "Ja", "correct": false, "because": "Intuition ungenau"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Erkennung von Optimierungspotenzialen?', 3, '[{"text": "Datenanalyse", "correct": true, "because": "Faktenbasis schaffen"}, {"text": "Schnelligkeit", "correct": false, "because": "Qualität zählt"}, {"text": "Vermutungen", "correct": false, "because": "Unzuverlässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Profiling zeigt Schwachstellen. b) Optimierung ist immer sofort umsetzbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) nicht immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Erkennung von Optimierungspotenzialen?', 5, '[{"text": "Kostensenkung", "correct": true, "because": "Effizienz steigt"}, {"text": "Zeitersparnis", "correct": true, "because": "Prozesse schneller"}, {"text": "Hohe Kosten", "correct": false, "because": "Kein Vorteil"}, {"text": "Schnelle Tests", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Erkennung unwichtig?', 3, '[{"text": "Leistungsdaten", "correct": false, "because": "Zeigt Schwächen"}, {"text": "Prozessschritte", "correct": false, "because": "Findet Engpässe"}, {"text": "Papierformat", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzt die Erkennung die Umsetzung?', 3, '[{"text": "Nein", "correct": true, "because": "Nur Vorbereitung"}, {"text": "Ja", "correct": false, "because": "Umsetzung separat"}]'),
